using System.Text.Json;using Archy.Features.Duplicates.DuplicateFindings;using Archy.Features.Workspaces.AcquireWorkspaceLock;
namespace Archy.Features.Integrations.Mcp.RunMcpServer;
public sealed class CheckDuplicateMcpTool:IMcpTool { public string Name=>"check_duplicate";public string Description=>"Return persisted duplicate candidates and evidence for a symbol, or abstain when no evidence exists.";public string InputSchemaJson=>"""{"type":"object","properties":{"stableId":{"type":"string","minLength":1,"description":"Stable identifier of the symbol to inspect."}},"required":["stableId"]}""";public async ValueTask<McpToolResult> ExecuteAsync(McpToolInvocation invocation,CancellationToken cancellationToken){if(!invocation.Arguments.TryGetProperty("stableId",out var stable)||string.IsNullOrWhiteSpace(stable.GetString()))return McpToolResult.Failure("stableId is required.");var lookup=new DuplicateFindingLookup(new WorkspaceLockManager(TimeProvider.System));var ids=await lookup.FindIdsByTargetAsync(invocation.Workspace.StateLocation,stable.GetString()!,cancellationToken);if(!ids.IsSuccess)return McpToolResult.Failure(ids.Problem!.Message);if(ids.Value!.Count==0)return McpToolResult.Success("{\"content\":[{\"type\":\"text\",\"text\":\"No persisted duplicate evidence exists for this symbol.\"}],\"structuredContent\":{\"abstention\":true,\"candidates\":[]}}");var repository=new DuplicateFindingRepository(TimeProvider.System,new WorkspaceLockManager(TimeProvider.System));var signals=new List<string>();foreach(var id in ids.Value){var history=await repository.ListObservationsAsync(invocation.Workspace.StateLocation,id,cancellationToken);if(!history.IsSuccess||history.Value!.Count==0)continue;var latest=history.Value[history.Value.Count-1];signals.Add($"{{\"findingId\":\"{id}\",\"confidence\":{latest.Confidence:R},\"signalCount\":{latest.Signals.Count}}}");}return McpToolResult.Success($"{{\"content\":[{{\"type\":\"text\",\"text\":\"Found {signals.Count} persisted duplicate candidate(s).\"}}],\"structuredContent\":{{\"abstention\":false,\"candidates\":[{string.Join(',',signals)}]}}}}");}}
